        }
        bytesWritten += DnsMessageHeader.Size;
        return true;
    }

    // Writes a question entry: encoded domain name + type + class.
    // Expands compression pointers if present (safe for names from responses).
    public bool TryWriteQuestion(
        scoped DnsEncodedName name,
        DnsRecordType type,
        DnsRecordClass @class = DnsRecordClass.Internet)
    {
        // Reserve the trailing 4 bytes for TYPE + CLASS up front so that encoding the
        // name cannot consume the space they require.
        Span<byte> destination = _destination[bytesWritten..];
        if (destination.Length < 4 ||
            !name.TryCopyEncodedTo(destination[..^4], out int nameWritten))
        {
            return false;
        }
        bytesWritten += nameWritten;

        BinaryPrimitives.WriteUInt16BigEndian(_destination[bytesWritten..], (ushort)type);
        bytesWritten += 2;

        BinaryPrimitives.WriteUInt16BigEndian(_destination[bytesWritten..], (ushort)@class);
        bytesWritten += 2;

        return true;
    }
}
